def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -(remaining ** 2) / bins + 0.1 * remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -np.exp(-remaining) - 0.1 * remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -1.0 / (remaining + 1e-7) - np.log(remaining + 1.0))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    target = bins * 0.25
    return np.where(remaining < 0, -np.inf, -np.abs(remaining - target))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = item / bins
    return np.where(remaining < 0, -np.inf, np.sin(np.pi * fill_ratio) - np.exp(np.maximum(0, 0.9 - fill_ratio)))
